import url('https://fonts.googleapis.com/css2?family=Epilogue:wght@700;900&family=Manrope:wght@400;500;700&display=swap');

:root {
    /* Stitch generated tokens - DARK (DEFAULT) */
    --background: #131313;
    --surface: #1b1b1b;
    --surface-elevated: #2a2a2a;
    --primary: #FFD700; /* Electric Gold */
    --on-background: #E2E2E2;
    --text-muted: #94a3b8;
    --whatsapp-green: #25D366;
    
    --header-blur: rgba(19, 19, 19, 0.7);
    --gold-glow: 0 0 20px rgba(255, 215, 0, 0.15);
    --transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
    --border-radius: 1.5rem;
}

/* LIGHT THEME */
[data-theme="light"] {
    --background: #f8fafc;
    --surface: #ffffff;
    --surface-elevated: #f1f5f9;
    --primary: #d97706; /* Warmer Gold for light */
    --on-background: #0f172a;
    --text-muted: #64748b;
    --header-blur: rgba(248, 250, 252, 0.7);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background-color: var(--background);
    color: var(--on-background);
    font-family: 'Manrope', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    transition: background-color 0.3s ease, color 0.3s ease;
}

h1, h2, h3 {
    font-family: 'Epilogue', sans-serif;
    text-transform: uppercase;
    letter-spacing: -0.04em;
    font-weight: 900;
}

.container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
}

/* NAVIGATION */
header {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 1000;
    background: var(--header-blur);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    padding: 1.2rem 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.nav-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-family: 'Epilogue', sans-serif;
    font-size: 1.6rem;
    color: var(--on-background);
    text-decoration: none;
    font-weight: 900;
}

.logo span { color: var(--primary); }

.nav-links { 
    display: flex; 
    gap: 2.5rem; 
    align-items: center; 
    list-style: none;
}

.nav-links a {
    text-decoration: none;
    color: var(--on-background);
    font-weight: 700;
    font-size: 0.8rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    transition: var(--transition);
    opacity: 0.7;
}

.nav-links a:hover, .nav-links a.active { 
    color: var(--primary); 
    opacity: 1;
}

#theme-toggle {
    background: none;
    border: none;
    color: var(--on-background);
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.5rem;
    transition: var(--transition);
}

#theme-toggle:hover {
    color: var(--primary);
    transform: rotate(20deg);
}

/* LANDING HERO (INDEX ONLY) */
.landing-hero {
    min-height: 80vh;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
    padding-top: 100px;
}

.landing-title {
    font-size: clamp(3rem, 8vw, 6rem);
    line-height: 0.9;
    margin-bottom: 2rem;
}

.landing-desc {
    font-size: 1.15rem;
    color: var(--text-muted);
    max-width: 500px;
    margin-bottom: 3rem;
    line-height: 1.8;
}

.landing-btns {
    display: flex;
    gap: 1.5rem;
}

.btn-primary-custom {
    background: var(--primary);
    color: #000;
    padding: 1.2rem 2.5rem;
    border-radius: 1rem;
    text-decoration: none;
    font-weight: 800;
    text-transform: uppercase;
    transition: var(--transition);
}

.btn-secondary-custom {
    background: transparent;
    color: var(--on-background);
    padding: 1.2rem 2.5rem;
    border-radius: 1rem;
    text-decoration: none;
    font-weight: 700;
    text-transform: uppercase;
    border: 1px solid rgba(255, 255, 255, 0.1);
    transition: var(--transition);
}

.btn-primary-custom:hover, .btn-secondary-custom:hover {
    transform: translateY(-5px);
    box-shadow: var(--gold-glow);
}

.landing-image {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
}

.floating-shoe {
    width: 140%;
    transform: rotate(-15deg);
    filter: drop-shadow(0 30px 60px rgba(0,0,0,0.8));
    animation: smoothFloat 6s ease-in-out infinite;
    z-index: 2;
}

.glow-effect {
    position: absolute;
    width: 300px;
    height: 300px;
    background: var(--primary);
    filter: blur(150px);
    opacity: 0.15;
    border-radius: 50%;
    z-index: 1;
}

@keyframes smoothFloat {
    0% { transform: rotate(-15deg) translateY(0); }
    50% { transform: rotate(-12deg) translateY(-30px); }
    100% { transform: rotate(-15deg) translateY(0); }
}

@media (max-width: 968px) {
