    --text-muted: #94a3b8;
    
    --header-blur: rgba(19, 19, 19, 0.7);
    --gold-glow: 0 0 20px rgba(255, 215, 0, 0.15);
    --transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background-color: var(--background);
    color: var(--on-background);
    font-family: 'Manrope', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
}

h1, h2, h3 {
    font-family: 'Epilogue', sans-serif;
    text-transform: uppercase;
    letter-spacing: -0.04em;
    font-weight: 900;
}

.container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
}

/* NAVIGATION - Glassmorphism */
header {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 1000;
    background: var(--header-blur);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    padding: 1.5rem 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.nav-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-family: 'Epilogue', sans-serif;
    font-size: 1.8rem;
    color: #fff;
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.logo span { color: var(--primary); }

.nav-links { display: flex; gap: 3rem; align-items: center; }
.nav-links a {
    text-decoration: none;
    color: #fff;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    transition: var(--transition);
}

.nav-links a:hover { color: var(--primary); }

/* HERO - Asymmetrical Design */
.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    padding-top: 100px;
}

.hero-grid {
    display: grid;
    grid-template-columns: 1.2fr 0.8fr;
    gap: 2rem;
    align-items: center;
}

.hero-title {
    font-size: clamp(3rem, 8vw, 6rem);
    line-height: 0.9;
    margin-bottom: 2rem;
}

.hero-desc {
    font-size: 1.1rem;
    max-width: 450px;
    margin-bottom: 3rem;
    color: var(--text-muted);
}

.hero-img-box {
    position: relative;
    padding: 2rem;
}

.hero-img-box img {
    width: 120%;
    transform: rotate(-15deg) translateY(20px);
    filter: drop-shadow(0 20px 50px rgba(0,0,0,0.8));
    transition: var(--transition);
}

.hero-img-box:hover img {
    transform: rotate(0deg) scale(1.1);
}

/* CARDS - Tonal Elevation */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 3rem;
}

.card {
    background: var(--surface);
    border-radius: 1.5rem;
    padding: 2rem;
    transition: var(--transition);
    position: relative;
}

.card:hover {
    background: var(--surface-elevated);
    transform: translateY(-10px);
    box-shadow: var(--gold-glow);
}

.card img {
    width: 100%;
    aspect-ratio: 1;
    object-fit: contain;
    margin-bottom: 1.5rem;
    transition: var(--transition);
}

.card:hover img { transform: scale(1.1) rotate(5deg); }

.card-title { font-size: 1.4rem; margin-bottom: 0.5rem; }
.card-price {
    font-size: 1.8rem;
    color: var(--primary);
    font-weight: 900;
    margin-bottom: 1.5rem;
    font-family: 'Epilogue', sans-serif;
}

/* BUTTONS */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    padding: 1.2rem 2.5rem;
    border-radius: 1rem;
    text-decoration: none;
    font-weight: 800;
    text-transform: uppercase;
    font-size: 0.9rem;
    transition: var(--transition);
    border: none;
}

.btn-primary { background: var(--primary); color: #000; }
.btn-primary:hover { transform: scale(1.05); }

.btn-whatsapp { background: var(--surface-elevated); color: #fff; border: 1px solid rgba(255,255,255,0.1); }
.btn-whatsapp:hover { border-color: var(--primary); color: var(--primary); }

/* MOBILE */
@media (max-width: 968px) {
    .nav-links { display: none; }
    .hero-grid { grid-template-columns: 1fr; text-align: center; }
    .hero-img-box img { width: 100%; transform: none; }
    .hero-title { font-size: 3.5rem; }
}
